/**
 * @param {string} s
 * @param {number} k
 * @return {number}
 */
var maxPalindromes = function(s, k) {
    let res = 0;

    for (let i = 0; i < s.length; i++) {
        let subStart = '';
        let subEnd = '';

        for (let j = i; j < s.length - Math.floor((s.length - i - 1) / 2); j++) {
            const created1 = subStart + subEnd;
            const sliced1 = s.slice(i, i + created1.length);

            if (created1.length >= k && created1 === sliced1) {
                res++;
                i += created1.length - 1;
                break;
            }

            const created2 = subStart + s[j] + subEnd;
            const sliced2 = s.slice(i, i + created2.length);

            if (created2.length >= k && created2 === sliced2) {
                res++;
                i += created2.length - 1;
                break;
            }

            subStart += s[j];
            subEnd = s[j] + subEnd;
        }
    }

    return res;
};

