var maxPalindromes = function (s, k) {
    const n = s.length;
    let res = 0;
    let start = 0;

    const check = (left, right) => {
        while (left < right && s[left] === s[right]) {
            left++;
            right--;
        }
        return left >= right;
    };

    for (let right = k - 1; right < n; right++) {
        let left = right - k + 1;
        if (left >= start && check(left, right)) {
            res++;
            start = right + 1;
            continue;
        }

        left = right - k;
        if (left >= start && check(left, right)) {
            res++;
            start = right + 1;
        }
    }

    return res;
};
